namespace EasyTrade.BrokerService.Entities.Alerts
{
    /// <summary>
    /// Snapshot of one alert row as db-adapter returned it. A trigger is never decided from a
    /// prior read of <see cref="TriggeredAt"/>; db-adapter's conditional write decides it.
    /// </summary>
    /// <param name="Id">Generated by the database.</param>
    /// <param name="AccountId">The account that owns the alert.</param>
    /// <param name="InstrumentId">The instrument whose price or P/L the alert watches.</param>
    /// <param name="Type">What the threshold measures.</param>
    /// <param name="Direction">Which strict crossing of the threshold triggers the alert.</param>
    /// <param name="Threshold">
    /// A price for <see cref="AlertType.TARGET_PRICE"/>, a percentage for
    /// <see cref="AlertType.PROFIT_LOSS"/>, which may be negative.
    /// </param>
    /// <param name="Enabled">User intent; a trigger does not change it.</param>
    /// <param name="ArmingRevision">
    /// Starts at 1 and increases on every enable. One arming is the pair
    /// (<paramref name="Id"/>, <paramref name="ArmingRevision"/>).
    /// </param>
    /// <param name="TriggeredAt">
    /// Set by db-adapter when the current arming triggers; null, together with
    /// <paramref name="TriggerValue"/>, until then.
    /// </param>
    /// <param name="TriggerValue">The observed value, rounded to 8 places, at the trigger.</param>
    /// <param name="Acknowledged">
    /// Whether the notification of the current arming has been acknowledged.
    /// </param>
    /// <param name="CreatedAt">Stamped by db-adapter.</param>
    public record Alert(
        Guid Id,
        Guid AccountId,
        Guid InstrumentId,
        AlertType Type,
        AlertDirection Direction,
        decimal Threshold,
        bool Enabled,
        int ArmingRevision,
        DateTimeOffset? TriggeredAt,
        decimal? TriggerValue,
        bool Acknowledged,
        DateTimeOffset CreatedAt
    );
}
